/**
 * OpenCode Hook Types
 * Based on opencode-with-hooks implementation
 */

export interface OpenCodeHookData {
  agent_type: string; // Usually 'claude' but can vary
  session_id: string;
  timestamp?: number;
  hook_event_name: string;
  tool_name?: string;
  tool_input?: Record<string, unknown>;
  tool_response?: Record<string, unknown>;
  [key: string]: unknown; // Allow additional fields
}

export interface OpenCodeToolCallData extends OpenCodeHookData {
  hook_event_name: 'tool_call' | 'tool_call_hook';
  tool_name: string;
  tool_input: Record<string, unknown>;
  tool_response?: Record<string, unknown>;
}

export interface OpenCodeFileReadData extends OpenCodeHookData {
  hook_event_name: 'file_read' | 'file_read_hook';
  tool_name: string; // Usually 'Read' or similar
  tool_input: {
    file_path: string;
    [key: string]: unknown;
  };
}

export interface OpenCodeFileEditedData extends OpenCodeHookData {
  hook_event_name: 'file_edited' | 'file_edited_hook';
  tool_name: string; // Edit, Write, etc.
  tool_input: {
    file_path: string;
    content?: string;
    old_string?: string;
    new_string?: string;
    [key: string]: unknown;
  };
}

export interface OpenCodeWebAccessData extends OpenCodeHookData {
  hook_event_name: 'web_access' | 'web_access_hook';
  tool_name: string; // WebFetch, WebSearch, etc.
  tool_input: {
    url?: string;
    query?: string;
    prompt?: string;
    [key: string]: unknown;
  };
}

export interface OpenCodeSessionStopData extends OpenCodeHookData {
  hook_event_name: 'session_stop' | 'session_stop_hook';
  // No tool_name for session stop
}

export type OpenCodeHookInput =
  | OpenCodeToolCallData
  | OpenCodeFileReadData
  | OpenCodeFileEditedData
  | OpenCodeWebAccessData
  | OpenCodeSessionStopData;

/**
 * OpenCode tool names (based on Claude tools)
 */
export const OPENCODE_TOOLS = {
  // File operations
  READ: 'Read',
  WRITE: 'Write',
  EDIT: 'Edit',
  MULTI_EDIT: 'MultiEdit',

  // Web operations
  WEB_FETCH: 'WebFetch',
  WEB_SEARCH: 'WebSearch',

  // System operations
  BASH: 'Bash',
  GREP: 'Grep',
  GLOB: 'Glob',
  LS: 'LS',

  // Other
  TODO_WRITE: 'TodoWrite',
  TASK: 'Task',
} as const;

export type OpenCodeToolName = (typeof OPENCODE_TOOLS)[keyof typeof OPENCODE_TOOLS] | string;

/**
 * Type guards
 */
export function isOpenCodeToolCall(data: unknown): data is OpenCodeToolCallData {
  return (
    typeof data === 'object' &&
    data !== null &&
    'hook_event_name' in data &&
    ((data as { hook_event_name: unknown }).hook_event_name === 'tool_call' ||
      (data as { hook_event_name: unknown }).hook_event_name === 'tool_call_hook')
  );
}

